//! Parity with the mod: every case in `companion/fixtures/status.ts` (generated by the mod's
//! `hooks/fixtures.test.ts`) gets the same card from the Rust port, field by field.
//!
//! `cardOf` there is `derive(pr)` (no kept reviews), `stepIndex(stage)`, the pill's key in
//! `PILL`, `metaOf(pr).isConflicted`, `mergeableOf(pr)` and `reviewsOf(pr)`.

use prw_core::gh::GhPr;
use prw_core::review::{Reviews, reviews_of};
use prw_core::status::{
    Checks, Mergeable, PillKind, Stage, Tone, derive, mergeable_of, meta_of, step_index,
};
use prw_core::{Entry, Shared, parse_shared};
use serde::{Deserialize, Serialize};
use serde_json::Value;

const SOURCE: &str = include_str!("../../../fixtures/status.ts");

#[derive(Deserialize)]
struct Case {
    name: String,
    #[expect(dead_code, reason = "read so a case without one fails to parse")]
    about: String,
    pr: Value,
    card: Value,
}

/// The mod's card, as data. Unknown fields fail: a card field the mod adds is one to port.
#[derive(Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct Card {
    stage: Stage,
    step: u8,
    tone: Tone,
    pill: String,
    pill_kind: Option<PillKind>,
    headline: String,
    is_moving: bool,
    checks: Checks,
    is_conflicted: bool,
    merge: Mergeable,
    reviews: Option<Reviews>,
}

fn card_of(pr: &GhPr) -> Card {
    let derived = derive(pr, None);

    Card {
        stage: derived.stage,
        step: step_index(derived.stage),
        tone: derived.tone,
        pill: derived.pill.text().to_owned(),
        pill_kind: Some(derived.pill),
        headline: derived.headline,
        is_moving: derived.is_moving,
        checks: derived.checks,
        is_conflicted: meta_of(pr).is_conflicted,
        merge: mergeable_of(pr),
        reviews: reviews_of(pr),
    }
}

fn cases() -> Vec<Case> {
    // After the export, so a `[` in the header comment can't be taken for the array's start.
    let export = SOURCE
        .find("export default")
        .expect("status.ts exports its cases");
    let start = export
        + SOURCE[export..]
            .find('[')
            .expect("status.ts holds a JSON array");
    serde_json::from_str(SOURCE[start..].trim_end()).expect("status.ts's array is JSON")
}

/// Every non-null value in `theirs` is in `ours`, at the same place: so no field of the
/// stored PR was misnamed in Rust and silently read as absent.
fn covers(theirs: &Value, ours: &Value, path: &str) -> Result<(), String> {
    match (theirs, ours) {
        (Value::Null, _) => Ok(()),
        (Value::Object(t), Value::Object(o)) => t.iter().try_for_each(|(key, value)| {
            covers(
                value,
                o.get(key).unwrap_or(&Value::Null),
                &format!("{path}.{key}"),
            )
        }),
        (Value::Array(t), Value::Array(o)) if t.len() == o.len() => t
            .iter()
            .zip(o)
            .enumerate()
            .try_for_each(|(i, (t, o))| covers(t, o, &format!("{path}[{i}]"))),
        _ if theirs == ours => Ok(()),
        _ => Err(format!(
            "{path}: the fixture says {theirs}, Rust read {ours}"
        )),
    }
}

#[test]
fn there_are_28_cases_named_apart() {
    let cases = cases();
    assert_eq!(cases.len(), 28);
    let mut names: Vec<&str> = cases.iter().map(|c| c.name.as_str()).collect();
    names.sort_unstable();
    names.dedup();
    assert_eq!(names.len(), 28);
}

#[test]
fn every_stored_pr_reads_whole() {
    for case in cases() {
        let pr: GhPr = serde_json::from_value(case.pr.clone()).unwrap();
        let ours = serde_json::to_value(&pr).unwrap();
        if let Err(why) = covers(&case.pr, &ours, "pr") {
            panic!("{}: {why}", case.name);
        }
    }
}

#[test]
fn every_card_is_the_mods() {
    let mut failures = Vec::new();
    for case in cases() {
        let pr: GhPr = serde_json::from_value(case.pr).unwrap();
        let theirs: Card = match serde_json::from_value(case.card.clone()) {
            Ok(card) => card,
            Err(error) => {
                failures.push(format!(
                    "{}: the fixture's card doesn't read as a Card: {error}",
                    case.name
                ));
                continue;
            }
        };
        let ours = card_of(&pr);
        let before = failures.len();
        let mut differ =
            |field: &str, same: bool, theirs: &dyn std::fmt::Debug, ours: &dyn std::fmt::Debug| {
                if !same {
                    failures.push(format!(
                        "{}: {field}\n    mod:  {theirs:?}\n    rust: {ours:?}",
                        case.name
                    ));
                }
            };
        differ(
            "stage",
            theirs.stage == ours.stage,
            &theirs.stage,
            &ours.stage,
        );
        differ("step", theirs.step == ours.step, &theirs.step, &ours.step);
        differ("tone", theirs.tone == ours.tone, &theirs.tone, &ours.tone);
        differ("pill", theirs.pill == ours.pill, &theirs.pill, &ours.pill);
        differ(
            "pillKind",
            theirs.pill_kind == ours.pill_kind,
            &theirs.pill_kind,
            &ours.pill_kind,
        );
        differ(
            "headline",
            theirs.headline == ours.headline,
            &theirs.headline,
            &ours.headline,
        );
        differ(
            "isMoving",
            theirs.is_moving == ours.is_moving,
            &theirs.is_moving,
            &ours.is_moving,
        );
        differ(
            "checks",
            theirs.checks == ours.checks,
            &theirs.checks,
            &ours.checks,
        );
        differ(
            "isConflicted",
            theirs.is_conflicted == ours.is_conflicted,
            &theirs.is_conflicted,
            &ours.is_conflicted,
        );
        differ(
            "merge",
            theirs.merge == ours.merge,
            &theirs.merge,
            &ours.merge,
        );
        differ(
            "reviews",
            theirs.reviews == ours.reviews,
            &theirs.reviews,
            &ours.reviews,
        );
        // Whatever the fields above miss (a nested field named differently): the whole card,
        // as the mod writes it.
        let written = serde_json::to_value(&ours).unwrap();
        if failures.len() == before && written != case.card {
            failures.push(format!(
                "{}: card JSON\n    mod:  {}\n    rust: {written}",
                case.name, case.card
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} difference(s) from the mod:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn every_stored_pr_round_trips_inside_results_json() {
    let mut shared = Shared {
        fetched_at: 1_791_373_800_000,
        next_at: 1_791_373_820_000,
        ..Shared::default()
    };
    for (i, case) in cases().into_iter().enumerate() {
        let pr: GhPr = serde_json::from_value(case.pr).unwrap();
        let entry = Entry {
            at: 1_791_373_800_000 + i64::try_from(i).unwrap(),
            pr: Some(pr.clone()),
            ..Entry::default()
        };
        shared.prs.insert(pr.url.clone(), entry);
    }
    let text = serde_json::to_string(&shared).unwrap();
    assert_eq!(parse_shared(&text).unwrap(), shared);
}
